import{Wrapper}from"../../utils/wrapper.js";import{caching}from"../../middlewares/caching.js";import{router as v1}from"./v1/index.js";import{ErrorHandler}from"../../libraries/errors/_errors.js";import{Router}from"express";const router=Router();router.use(caching);const routes=[v1];for(const route of routes){router.use(route)}router.use(Wrapper((req,res,next)=>{throw new ErrorHandler({code:404,message:"Not Found",details:[]})}));router.use((error,req,res,next)=>{res.status(error.code||500).json({success:false,message:error.message,error:{details:error.details},data:null})});export{router};